/// Parsed outlines, held: a shape is asked for its path on every size change.
private nonisolated final class DiscordBrandIconCache: @unchecked Sendable {
    static let shared = DiscordBrandIconCache()

    private let lock = NSLock()
    private var parsed: [DiscordBrandIcon: [DiscordBrandIcon.Part]] = [:]

    func parts(for icon: DiscordBrandIcon) -> [DiscordBrandIcon.Part] {
        lock.lock()
        defer { lock.unlock() }
        if let hit = parsed[icon] { return hit }
        let built = icon.outlines.compactMap { outline, evenOdd in
            VectorPath.parse(outline).map { DiscordBrandIcon.Part(path: $0, evenOdd: evenOdd) }
        }
        parsed[icon] = built
        return built
    }
}

/// One of Discord's marks, filled with the current foreground style, square in
/// whatever frame it is given.
struct DiscordBrandIconView: View {
    var icon: DiscordBrandIcon

    var body: some View {
        ZStack {
            ForEach(Array(icon.parts.enumerated()), id: \.offset) { index, part in
                DiscordBrandIconPart(icon: icon, index: index).fill(style: FillStyle(eoFill: part.evenOdd))
            }
        }
        .aspectRatio(1, contentMode: .fit)
        .accessibilityHidden(true)
    }
}

/// One outline, scaled from the 24-unit grid into its rect and centred.
///
/// Named by icon and index rather than holding its `CGPath`, as `BrandGlyph`
/// names its service: a `Shape` is `Sendable`, and the parsed path is the
/// cache's to hold.
nonisolated struct DiscordBrandIconPart: Shape {
    var icon: DiscordBrandIcon
    var index: Int

    func path(in rect: CGRect) -> Path {
        let parts = icon.parts
        guard parts.indices.contains(index) else { return Path() }
        let path = parts[index].path
        let scale = min(rect.width, rect.height) / 24
        var transform = CGAffineTransform(
            translationX: rect.midX - 12 * scale,
            y: rect.midY - 12 * scale
        )
        .scaledBy(x: scale, y: scale)
        guard let scaled = path.copy(using: &transform) else { return Path() }
        return Path(scaled)
    }
}
